1→import { randomUUID } from 'node:crypto';
2→const typed = (message, code) => Object.assign(new Error(message), { code });
3→const record = (value) => value !== null && typeof value === 'object' && !Array.isArray(value);
4→const json = (value) => JSON.parse(JSON.stringify(value));
5→function jsonValue(value, seen = new Set()) {
6→  if (value === null || typeof value === 'string' || typeof value === 'boolean') return true;
7→  if (typeof value === 'number') return Number.isFinite(value);
8→  if (typeof value !== 'object' || seen.has(value)) return false;
9→  seen.add(value);
10→  const values = Array.isArray(value)
11→    ? value
12→    : Object.getPrototypeOf(value) === Object.prototype
13→      ? Object.values(value)
14→      : null;
15→  const valid = values !== null && values.every((item) => jsonValue(item, seen));
16→  seen.delete(value);
17→  return valid;
18→}
19→function validResult(value, op) {
20→  return record(value) && value.op === op && typeof value.status === 'string' && value.status.length > 0
21→    && typeof value.summary === 'string' && Array.isArray(value.payload) && Array.isArray(value.refs)
22→    && record(value.cost) && record(value.provenance) && jsonValue(value);
23→}
