25→export class CapabilityRegistry {
26→  constructor(opts = {}) {
27→    if (!record(opts.capabilities ?? {})) throw new TypeError('capabilities must be a closed object registry');
28→    if (!record(opts.contexts ?? {})) throw new TypeError('capability contexts must be a closed object registry');
29→    if (!Number.isSafeInteger(opts.maxBudgetTokens) || opts.maxBudgetTokens <= 0) throw new TypeError('maxBudgetTokens must be deployment-derived');
30→    if (!Number.isSafeInteger(opts.maxEnvelopeBytes) || opts.maxEnvelopeBytes <= 0) throw new TypeError('maxEnvelopeBytes must be deployment-derived');
31→    if (opts.root !== undefined && (typeof opts.root !== 'string' || opts.root.length === 0)) throw new TypeError('capability root must be a non-empty string');
32→    if (opts.record !== undefined && opts.record !== null && typeof opts.record !== 'function') throw new TypeError('capability record sink must be a function');
33→    if (Object.keys(opts.capabilities ?? {}).length > 0 && typeof opts.record !== 'function') throw new TypeError('non-empty capability registry requires a provenance record sink');
34→    this.maxBudgetTokens = opts.maxBudgetTokens; this.maxEnvelopeBytes = opts.maxEnvelopeBytes; this.root = opts.root; this.record = opts.record ?? null; this.recordFailure = null; this.entries = new Map();
35→    for (const name of Object.keys(opts.contexts ?? {})) if (!Object.hasOwn(opts.capabilities ?? {}, name)) throw new TypeError(`capability context has no registration: ${name}`);
36→    for (const [name, capability] of Object.entries(opts.capabilities ?? {})) {
37→      if (!/^[A-Za-z0-9._:-]{1,128}$/.test(name) || !capability || typeof capability.card !== 'function' || typeof capability.invoke !== 'function') throw new TypeError(`invalid capability registration: ${name}`);
38→      const card = capability.card(); const ops = record(card?.ops) ? Object.keys(card.ops) : [];
39→      if (!record(card) || card.name !== name || ops.length === 0 || ops.some((op) => !/^[A-Za-z0-9._:-]{1,256}$/.test(op))
40→        || !jsonValue(card) || Buffer.byteLength(JSON.stringify(card)) > this.maxEnvelopeBytes) throw new TypeError(`invalid capability card: ${name}`);
41→      const context = opts.contexts?.[name] ?? null;
42→      if (context !== null && typeof context !== 'function' && (!record(context) || !jsonValue(context))) throw new TypeError(`invalid capability context: ${name}`);
43→      this.entries.set(name, { capability, context, card: Object.freeze(json(card)) });
44→    }
45→  }
46→  _record(event) {
47→    if (this.recordFailure) throw this.recordFailure;
48→    if (!this.record) return;
49→    try { this.record(event); }
50→    catch (cause) {
51→      this.recordFailure = typed('capability provenance sink unavailable; restart and reconcile before further capability use', 'capability_record_unavailable');
52→      this.recordFailure.cause = cause;
53→      throw this.recordFailure;
54→    }
55→  }
56→  cards() { if (this.recordFailure) throw this.recordFailure; return [...this.entries].sort(([a], [b]) => a.localeCompare(b)).map(([name, entry]) => Object.freeze({ ...json(entry.card), name })); }
57→  _entry(name) { const entry = this.entries.get(name); if (!entry) throw typed('unknown capability', 'capability_not_found'); return entry; }
58→  _op(entry, op) { if (typeof op !== 'string' || !Object.hasOwn(entry.card.ops, op)) throw typed('operation not advertised by capability', 'capability_op_unavailable'); }
59→  _actor(ctx = {}) {
60→    const actor = ctx.actor ?? 'orchestrator';
61→    if (typeof actor !== 'string' || actor.length === 0 || actor.length > 256) throw typed('capability actor invalid', 'capability_actor_invalid');
62→    return actor;
63→  }
64→  _ctx(ctx = {}) {
65→    if (!Number.isSafeInteger(ctx.budgetTokens) || ctx.budgetTokens <= 0 || ctx.budgetTokens > this.maxBudgetTokens) throw typed('capability budget outside deployment policy', 'capability_budget_invalid');
66→    if (ctx.signal?.aborted) throw typed('capability invocation cancelled', 'cancelled');
67→    const actor = this._actor(ctx);
68→    return { budgetTokens: ctx.budgetTokens, signal: ctx.signal, actor, ...(this.root === undefined ? {} : { root: this.root }) };
69→  }
70→  _capabilityCtx(entry, request, safe) {
71→    const resolved = typeof entry.context === 'function' ? entry.context(Object.freeze(json(request))) : entry.context;
72→    if (resolved === null || resolved === undefined) return safe;
73→    if (!record(resolved) || !jsonValue(resolved) || Buffer.byteLength(JSON.stringify(resolved)) > this.maxEnvelopeBytes) throw typed('deployment capability context invalid', 'capability_context_invalid');
74→    for (const key of ['actor', 'budgetTokens', 'root', 'signal']) if (Object.hasOwn(resolved, key)) throw typed('deployment capability context attempted to override registry authority', 'capability_context_forbidden');
75→    return { ...json(resolved), ...safe };
76→  }
77→  _validate(result, op, budgetTokens) {
78→    if (!validResult(result, op)) throw typed('capability returned an invalid ACI envelope', 'capability_result_invalid');
79→    if ((Object.hasOwn(result.provenance, 'mergeAuthority') && result.provenance.mergeAuthority !== false)
