81→      throw typed('capability attempted to claim coordinator authority', 'capability_authority_forbidden');
82→    }
83→    if (Buffer.byteLength(JSON.stringify(result)) > this.maxEnvelopeBytes) throw typed('capability result exceeded deployment envelope ceiling', 'capability_result_oversize');
84→    if (Buffer.byteLength(JSON.stringify(result.payload)) > budgetTokens * 4) throw typed('capability payload exceeded invocation budget', 'capability_result_oversize');
85→    return Object.freeze(json(result));
86→  }
87→  async _run(action, name, op, fn, ctx) {
88→    const invocationId = randomUUID(); const actor = this._actor(ctx);
89→    const auditName = typeof name === 'string' && name.length <= 128 ? name : '[invalid]';
90→    const auditOp = typeof op === 'string' && op.length <= 256 ? op : '[invalid]';
91→    this._record({ kind: 'capability.op.started', actor, invocationId, action, capability: auditName, op: auditOp });
92→    try {
93→      const safe = this._ctx(ctx);
94→      const result = this._validate(await fn(safe), op, safe.budgetTokens);
95→      this._record({ kind: 'capability.op.completed', actor, invocationId, action, capability: auditName, op: auditOp, status: result.status.slice(0, 128), digests: result.refs.map((ref) => ref.digest).filter((digest) => typeof digest === 'string' && digest.length <= 256).slice(0, 256) });
96→      return result;
97→    } catch (error) {
98→      this._record({ kind: 'capability.op.refused', actor, invocationId, action, capability: auditName, op: auditOp, code: typeof error?.code === 'string' && error.code.length <= 128 ? error.code : 'capability_failed' });
99→      throw error;
100→    }
101→  }
102→  async invoke(name, op, args, ctx) {
103→    return this._run('invoke', name, op, (safe) => {
104→      const entry = this._entry(name); this._op(entry, op);
105→      if (!record(args ?? {}) || !jsonValue(args ?? {}) || Buffer.byteLength(JSON.stringify(args ?? {})) > this.maxEnvelopeBytes) throw typed('capability arguments must be a bounded JSON object', 'capability_args_invalid');
106→      return entry.capability.invoke(op, json(args ?? {}), this._capabilityCtx(entry, { action: 'invoke', op, args: args ?? {} }, safe));
107→    }, ctx);
108→  }
