111→      const entry = this._entry(name); this._op(entry, op);
112→      if (typeof entry.capability.resume !== 'function') throw typed('capability does not support resume', 'capability_resume_unavailable');
113→      if (!record(ref) || !jsonValue(ref) || Buffer.byteLength(JSON.stringify(ref)) > this.maxEnvelopeBytes || typeof cursor !== 'string' || cursor.length === 0 || Buffer.byteLength(cursor) > this.maxEnvelopeBytes) throw typed('capability resume reference invalid', 'capability_resume_invalid');
