127→export class McpFleetServer {
128→  constructor(opts) {
129→    if (!opts?.coordinator || !opts?.coordination || !record(opts.principal)) throw new TypeError('MCP northbound requires coordinator, coordination, and injected principal');
130→    for (const method of ['admitMcpCall', 'completeMcpCall', 'failMcpCall', 'mcpCall', 'recordMcpAudit']) {
131→      if (typeof opts.coordination[method] !== 'function') throw new TypeError(`coordination authority is missing ${method}()`);
132→    }
133→    if (typeof opts.takeToolQuota !== 'function') throw new TypeError('MCP northbound requires an injected tool quota authority');
134→    this.coordinator = opts.coordinator;
135→    this.coordination = opts.coordination;
136→    this.principal = Object.freeze(clone(opts.principal));
137→    this.repoIds = new Set(opts.repoIds ?? []);
138→    this.now = opts.now ?? Date.now;
139→    this.maxWaitMs = opts.maxWaitMs ?? 25_000;
140→    this.maxMessageBytes = opts.maxMessageBytes;
141→    this.takeToolQuota = opts.takeToolQuota;
142→    if (!Number.isSafeInteger(this.maxWaitMs) || this.maxWaitMs <= 0) throw new TypeError('maxWaitMs must be a positive safe integer');
143→    if (!Number.isSafeInteger(this.maxMessageBytes) || this.maxMessageBytes <= 0) throw new TypeError('maxMessageBytes must be a deployment-derived positive safe integer');
